static const z_t5680_t _zag3308 = { { .data = "run", .size = 3 }, { .data = "", .size = 0 }, { .length = 5, .data = _zag3307 }, { .data = "static void z_@@NAME@@_run(void* p) {\n    z_@@NAME@@_blk* b = (z_@@NAME@@_blk*)p;\n    Z_ATOMIC_STORE(&b->tid, z_thread_self_id(), Z_RELEASE);\n    /* a task answering nothing stores nothing */\n#if @@P0_NULL@@\n    (void)b->task.vtable->@@SLOT.create.task.call@@(b->task.data);\n#else\n    b->result = b->task.vtable->@@SLOT.create.task.call@@(b->task.data);\n#endif\n    z_@@ARG.create.task@@_destroy(&b->task);\n    Z_ATOMIC_STORE(&b->finished, 1, Z_RELEASE);\n    /* detached first: the handle let go, so the thread cleans up */\n    if (Z_ATOMIC_ADD(&b->done, 1, Z_ACQREL) == 1) {\n        @@P0_DESTROY@@(&b->result);\n        free(b);\n    }\n}", .size = 635 } };
